#!/usr/bin/env python3
"""Generate Python, JavaScript and C++ protocol tables from protocol/a16_protocol.json.

Usage: gen_protocol.py [--check]

--check exits non-zero if any generated file is out of date (used by the tests).
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SPEC = ROOT / "protocol" / "a16_protocol.json"
OUT_PY = ROOT / "custom_components" / "realiser_a16" / "a16" / "protocol_gen.py"
OUT_JS = ROOT / "custom_components" / "realiser_a16" / "frontend" / "protocol_gen.js"
OUT_H = ROOT / "esp32" / "include" / "a16_protocol.h"

BANNER = "GENERATED by tools/gen_protocol.py from protocol/a16_protocol.json - do not edit."


def _c_ident(name: str) -> str:
    return "".join(ch if ch.isalnum() else "_" for ch in name).upper()


def gen_python(s: dict) -> str:
    lines = [f'"""{BANNER}"""', "", "from __future__ import annotations", ""]
    lines += [
        f"DEFAULT_PORT = {s['default_port']}",
        f"VOLUME_MIN = {s['volume_min']}",
        f"VOLUME_MAX = {s['volume_max']}",
        f"PRESET_COUNT = {s['preset_count']}",
        f"PRESET_A_BASE = 0x{s['preset_a_base']}",
        f"PRESET_B_BASE = 0x{s['preset_b_base']}",
        f"SPEAKER_BASE = 0x{s['speaker_base']}",
        f"SPEAKER_COMMAND_MAX = {s['speaker_command_max']}",
        "",
        "# IR remote keys: name -> command code",
        "IR_KEYS: dict[str, int] = {",
    ]
    lines += [f'    "{n}": 0x{c},  # {label}' for n, c, label in s["ir_keys"]]
    lines += ["}", "", "# Sources: id -> (command code, IN= response value)"]
    lines += ["SOURCES: dict[str, tuple[int, str]] = {"]
    lines += [f'    "{n}": (0x{c}, "{label}"),' for n, c, label in s["sources"]]
    lines += ["}", "", "# Non-IR commands: name -> command code", "COMMANDS: dict[str, int] = {"]
    lines += [f'    "{n}": 0x{c},  # {label}' for n, c, label in s["commands"]]
    lines += ["}", "", "# Speakers: id -> (name, type, grid_row, grid_col)"]
    lines += ["SPEAKERS: dict[int, tuple[str, str, int, int]] = {"]
    lines += [f'    {i}: ("{n}", "{t}", {r}, {c}),' for i, n, t, r, c in s["speakers"]]
    lines += ["}", ""]
    return "\n".join(lines)


def gen_js(s: dict) -> str:
    def obj(rows):
        return json.dumps(rows, separators=(",", ":"))

    return "\n".join(
        [
            f"// {BANNER}",
            f"export const VOLUME_MIN = {s['volume_min']};",
            f"export const VOLUME_MAX = {s['volume_max']};",
            f"export const PRESET_COUNT = {s['preset_count']};",
            "// [name, label]",
            f"export const IR_KEYS = {obj([[n, label] for n, _, label in s['ir_keys']])};",
            "// [id, label]",
            f"export const SOURCES = {obj([[n, label] for n, _, label in s['sources']])};",
            "// [id, name, type, row, col]",
            f"export const SPEAKERS = {obj(s['speakers'])};",
            "",
        ]
    )


def gen_header(s: dict) -> str:
    lines = [
        f"// {BANNER}",
        "#pragma once",
        "#include <stdint.h>",
        "",
        "namespace a16 {",
        "",
        f"constexpr uint16_t DEFAULT_PORT = {s['default_port']};",
        f"constexpr uint8_t VOLUME_MIN = {s['volume_min']};",
        f"constexpr uint8_t VOLUME_MAX = {s['volume_max']};",
        f"constexpr uint8_t PRESET_COUNT = {s['preset_count']};",
        f"constexpr uint8_t PRESET_A_BASE = 0x{s['preset_a_base']};",
        f"constexpr uint8_t PRESET_B_BASE = 0x{s['preset_b_base']};",
        f"constexpr uint8_t SPEAKER_BASE = 0x{s['speaker_base']};",
        f"constexpr uint8_t SPEAKER_COMMAND_MAX = {s['speaker_command_max']};",
        "",
        "// Send as two lowercase hex digits followed by \\r\\n.",
        "enum Cmd : uint8_t {",
    ]
    lines += [f"    KEY_{_c_ident(n)} = 0x{c},  // {label}" for n, c, label in s["ir_keys"]]
    lines += [f"    SRC_{_c_ident(n)} = 0x{c},  // {label}" for n, c, label in s["sources"]]
    lines += [f"    CMD_{_c_ident(n)} = 0x{c},  // {label}" for n, c, label in s["commands"]]
    lines += [
        "};",
        "",
        "struct Named { const char* name; uint8_t code; const char* label; };",
        "",
        "constexpr Named IR_KEYS[] = {",
    ]
    lines += [f'    {{"{n}", 0x{c}, "{label}"}},' for n, c, label in s["ir_keys"]]
    lines += ["};", "", "// label is the value reported in IN=", "constexpr Named SOURCES[] = {"]
    lines += [f'    {{"{n}", 0x{c}, "{label}"}},' for n, c, label in s["sources"]]
    lines += [
        "};",
        "",
        "enum class SpeakerType : uint8_t { FLOOR, HEIGHT, OVERHEAD, UNDER, LFE };",
        "",
        "struct Speaker { uint8_t id; const char* name; SpeakerType type; uint8_t row; uint8_t col; };",
        "",
        "// Grid position refers to the 9x7 A16 LCD loudspeaker map.",
        "constexpr Speaker SPEAKERS[] = {",
    ]
    lines += [
        f'    {{{i}, "{n}", SpeakerType::{t.upper()}, {r}, {c}}},' for i, n, t, r, c in s["speakers"]
    ]
    lines += ["};", "", "}  // namespace a16", ""]
    return "\n".join(lines)


def main() -> int:
    spec = json.loads(SPEC.read_text())
    outputs = {OUT_PY: gen_python(spec), OUT_JS: gen_js(spec), OUT_H: gen_header(spec)}
    check = "--check" in sys.argv
    stale = []
    for path, text in outputs.items():
        if check:
            if not path.exists() or path.read_text() != text:
                stale.append(path)
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
            print(f"wrote {path.relative_to(ROOT)}")
    if stale:
        print("out of date: " + ", ".join(str(p.relative_to(ROOT)) for p in stale))
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
